function solve(input) {
    if (typeof input !== 'string') return null;
    if (input.length === 0) return null;

    // Check for lowercase
    for (let i = 0; i < input.length; i++) {
        if (input[i] >= 'a' && input[i] <= 'z') return null;
    }

    // Valid characters
    const validChars = new Set(['I', 'V', 'X', 'L', 'C', 'D', 'M']);
    for (let i = 0; i < input.length; i++) {
        if (!validChars.has(input[i])) return null;
    }

    // Canonical validation using regex
    const pattern = /^(M{0,3})(CM|CD|D?C{0,3})(XC|XL|L?X{0,3})(IX|IV|V?I{0,3})$/;
    const match = input.match(pattern);
    if (!match) return null;

    // Additional check: the pattern above allows empty groups, but we need at least one character
    // Since input is non-empty and all chars are valid, this should be fine.
    // But let's be extra careful: the pattern requires at least one of the groups to match something
    // Actually, if input is "M", it matches M{1} and empty others. That's valid.
    // If input is empty, we already returned null.

    // Now convert to integer
    const values = {
        'I': 1,
        'V': 5,
        'X': 10,
        'L': 50,
        'C': 100,
        'D': 500,
        'M': 1000
    };

    let result = 0;
    let prev = 0;

    // Process from right to left
    for (let i = input.length - 1; i >= 0; i--) {
        const val = values[input[i]];
        if (val < prev) {
            result -= val;
        } else {
            result += val;
        }
        prev = val;
    }

    // Check range 1 to 3999
    if (result < 1 || result > 3999) return null;

    return result;
}

