function solve(input) {
    if (typeof input !== "string") return null;
    const s = input;
    if (s.length === 0) return null;

    const validChars = new Set(["I", "V", "X", "L", "C", "D", "M"]);
    for (const ch of s) {
        if (!validChars.has(ch)) return null;
    }

    const values = {
        I: 1,
        V: 5,
        X: 10,
        L: 50,
        C: 100,
        D: 500,
        M: 1000
    };

    // Check lowercase: since we already checked validChars, lowercase will fail there.
    // But also ensure no lowercase at all (already covered).

    // Validate canonical form:
    // 1. No more than three repeats of I, X, C, M
    // 2. Only valid subtractive pairs: IV, IX, XL, XC, CD, CM
    // 3. No other consecutive patterns that would be invalid

    const n = s.length;
    let total = 0;
    let i = 0;

    while (i < n) {
        const cur = values[s[i]];

        // Check for subtractive pair
        if (i + 1 < n) {
            const next = values[s[i + 1]];
            if (cur < next) {
                // Must be a valid subtractive pair
                const pair = s[i] + s[i + 1];
                const validPairs = new Set(["IV", "IX", "XL", "XC", "CD", "CM"]);
                if (!validPairs.has(pair)) {
                    return null;
                }
                total += next - cur;
                i += 2;
                continue;
            }
        }

        // Check repeat limit for I, X, C, M
        if (s[i] === "I" || s[i] === "X" || s[i] === "C" || s[i] === "M") {
            let count = 0;
            let j = i;
            while (j < n && s[j] === s[i]) {
                count++;
                j++;
            }
            if (count > 3) {
                return null;
            }
            total += cur * count;
            i += count;
            continue;
        }

        // For V, L, D: they should not be repeated
        if (s[i] === "V" || s[i] === "L" || s[i] === "D") {
            if (i + 1 < n && s[i + 1] === s[i]) {
                return null;
            }
            total += cur;
            i += 1;
            continue;
        }

        // Should not reach here
        return null;
    }

    if (total < 1 || total > 3999) return null;

    return total;
}

