function solve(input) {
    // Validate input type and canonical form strictly
    if (typeof input !== 'string' || input.length === 0) return null;
    if (input !== input.toUpperCase()) return null;

    const map = { I: 1, V: 5, X: 10, L: 50, C: 100, D: 500, M: 1000 };

    // Check each character is a valid Roman numeral character
    for (const ch of input) {
        if (!(ch in map)) return null;
    }

    // Validate subtractive pairs and repetition rules
    // Subtractive pairs: IV, IX, XL, XC, CD, CM
    // No more than three repeats of I, X, C, M
    // V, L, D cannot be repeated

    // Check for invalid subtractive patterns
    for (let i = 0; i < input.length - 1; i++) {
        const c1 = input[i];
        const c2 = input[i + 1];
        const v1 = map[c1];
        const v2 = map[c2];
        if (v1 < v2) {
            // Must be a valid subtractive pair
            const pair = c1 + c2;
            if (!['IV', 'IX', 'XL', 'XC', 'CD', 'CM'].includes(pair)) {
                return null;
            }
        }
    }

    // Check repetition rules
    // I, X, C, M can appear at most 3 times consecutively
    // V, L, D cannot appear more than once consecutively
    let count = 1;
    for (let i = 1; i < input.length; i++) {
        if (input[i] === input[i - 1]) {
            count++;
            const ch = input[i];
            if ('VLD'.includes(ch)) {
                return null; // V, L, D cannot be repeated
            }
            if (count > 3) {
                return null; // I, X, C, M cannot be repeated more than 3 times
            }
        } else {
            count = 1;
        }
    }

    // Convert to integer
    let result = 0;
    for (let i = 0; i < input.length; i++) {
        const curr = map[input[i]];
        const next = i + 1 < input.length ? map[input[i + 1]] : 0;
        if (curr < next) {
            result -= curr;
        } else {
            result += curr;
        }
    }

    // Validate range 1 to 3999
    if (result < 1 || result > 3999) return null;

    return result;
}

