function solve(input) {
    // Handle null/undefined
    if (input == null) return "0.00";
    let s = String(input).trim();
    if (s === "" || s === "-") return "0.00";

    // Handle negative sign
    let neg = false;
    if (s[0] === '-') {
        neg = true;
        s = s.slice(1);
    } else if (s[0] === '+') {
        s = s.slice(1);
    }

    if (s === "") return "0.00";

    // Check if it's a valid number format (optional but safe)
    // Split into integer and fractional parts
    let dotIdx = s.indexOf('.');
    let intPart, fracPart;
    if (dotIdx === -1) {
        intPart = s;
        fracPart = "";
    } else {
        intPart = s.slice(0, dotIdx);
        fracPart = s.slice(dotIdx + 1);
    }

    // Remove leading zeros from intPart for easier processing, but keep at least one digit
    // Actually, let's work with the digits directly.

    // We need to round to 2 decimal places.
    // The relevant digits are: intPart + first 3 digits of fracPart.
    // If fracPart has fewer than 3 digits, pad with zeros.

    let digits = intPart + fracPart;
    let dotPos = intPart.length; // Position of decimal point in the combined digit string

    // If intPart is empty (e.g., ".5"), treat as 0
    if (intPart === "") {
        intPart = "0";
        digits = intPart + fracPart;
        dotPos = intPart.length;
