    // We need at least dotPos + 3 digits to consider the third decimal place
    // Pad fracPart with zeros if necessary
    while (fracPart.length < 3) {
        fracPart = fracPart + "0";
    }
    // Rebuild digits with padded fracPart
    digits = intPart + fracPart;

    // The digit at position dotPos + 2 is the third decimal place (0-indexed: dotPos is where '.' is, so dotPos+0 is first decimal, dotPos+1 is second, dotPos+2 is third)
    // Wait: intPart is before decimal. If intPart is "2", dotPos=1.
    // digits[0] = '2' (ones place)
    // digits[1] = first decimal digit
    // digits[2] = second decimal digit
    // digits[3] = third decimal digit

    let thirdDigitIdx = dotPos + 2;
    let secondDigitIdx = dotPos + 1;

    // Ensure we have enough digits
    if (thirdDigitIdx >= digits.length) {
        // Not enough digits, pad with zeros
        while (digits.length <= thirdDigitIdx) {
            digits = digits + "0";
        }
    }

    let thirdDigit = parseInt(digits[thirdDigitIdx], 10);
    let secondDigit = parseInt(digits[secondDigitIdx], 10);

    // Check if there are any non-zero digits after the third decimal place
    let hasTrailingNonZero = false;
    for (let i = thirdDigitIdx + 1; i < digits.length; i++) {
        if (digits[i] !== '0') {
            hasTrailingNonZero = true;
            break;
        }
    }

    let roundUp = false;
    if (thirdDigit > 5) {
        roundUp = true;
    } else if (thirdDigit < 5) {
        roundUp = false;
    } else {
