    const startDow = fromDate.getUTCDay(); // 0-6
    const endDow = toDate.getUTCDay();

    // Number of days in the half-open range [from, to)
    const msPerDay = 24 * 60 * 60 * 1000;
    const numDays = Math.round((toDate.getTime() - fromDate.getTime()) / msPerDay);

    if (numDays <= 0) return 0;

    // Full weeks contribute 5 weekdays each
    const fullWeeks = Math.floor(numDays / 7);
    let count = fullWeeks * 5;

    // Remaining days
    const remaining = numDays % 7;
    // Simulate the remaining days starting from startDow
    for (let i = 0; i < remaining; i++) {
        const dow = (startDow + i) % 7;
        if (dow >= 1 && dow <= 5) {
            count++;
        }
    }

    return count;
}

