  const words = text.split(/\s+/).filter(w => w.length > 0);
  if (words.length === 0) return [];

  const lines = [];
  let current = '';

  for (const word of words) {
    if (word.length > width) {
      // word longer than width goes on its own line
      if (current !== '') {
        lines.push(current);
        current = '';
      }
      lines.push(word);
    } else {
      if (current === '') {
        current = word;
      } else {
        const candidate = current + ' ' + word;
        if (candidate.length <= width) {
          current = candidate;
        } else {
          lines.push(current);
          current = word;
        }
      }
    }
  }

  if (current !== '') {
    lines.push(current);
  }

  return lines;
}

