    // We have:
    // b = (p * a + q) % n  =>  p*a + q ≡ b (mod n)
    // c = (p * b + q) % n  =>  p*b + q ≡ c (mod n)
    // Subtract: p*(b - a) ≡ c - b (mod n)
    // Let d = b - a, e = c - b
    // We need to solve: p*d ≡ e (mod n)
    // This is a linear congruence. It has a solution if gcd(d, n) divides e.

    const d = (b - a + n) % n;
    const e = (c - b + n) % n;

    // Compute gcd(d, n)
    function gcd(x, y) {
        while (y) {
            [x, y] = [y, x % y];
        }
        return x;
    }

    const g = gcd(d, n);
    if (e % g !== 0) {
        // No solution? This shouldn't happen for a valid LCG with modulus n.
        // But let's handle it gracefully.
        return 0;
    }

    // Solve p*d ≡ e (mod n)
    // Divide by g: p*(d/g) ≡ (e/g) (mod n/g)
    const dPrime = d / g;
    const ePrime = e / g;
    const nPrime = n / g;

    // Find modular inverse of dPrime mod nPrime
    // dPrime * inv ≡ 1 (mod nPrime)
    // Use extended Euclidean algorithm

    function modInverse(a, m) {
        // a and m are coprime
        let m0 = m;
        let x0 = 0, x1 = 1;
        while (a > 1) {
            let q = Math.floor(a / m);
            [m, a] = [a, m - q * a];
            [x0, x1] = [x1, x0 - q * x1];
        }
        if (x1 < 0) x1 += m0;
        return x1;
    }

    // dPrime and nPrime should be coprime
    const inv = modInverse(dPrime % nPrime, nPrime);
    const p = (BigInt(ePrime) * BigInt(inv)) % BigInt(nPrime);

    // Now compute q: q ≡ b - p*a (mod n)
