    // Helper to parse ISO date "YYYY-MM-DD" into a Date object at UTC midnight
    function parseDateUTC(iso) {
        const parts = iso.split("-");
        const y = parseInt(parts[0], 10);
        const m = parseInt(parts[1], 10);
        const d = parseInt(parts[2], 10);
        // Use Date.UTC to avoid local timezone issues
        return new Date(Date.UTC(y, m - 1, d));
    }

    const start = parseDateUTC(from);
    const end = parseDateUTC(to);

    // Count days in [start, end)
    const msPerDay = 24 * 60 * 60 * 1000;
    const totalDays = Math.floor((end - start) / msPerDay);

    // If no days, return 0
    if (totalDays <= 0) return 0;

    // Get the day of week for the start date (0=Sun, 1=Mon, ..., 5=Fri, 6=Sat)
    const startDay = start.getUTCDay();

    // We need to count weekdays (Mon-Fri) in totalDays days starting from startDay.
    // We can compute this using cycles of 7 days.
    const fullWeeks = Math.floor(totalDays / 7);
    const remainingDays = totalDays % 7;

    // Each full week has 5 weekdays.
    let weekdays = fullWeeks * 5;

    // Now count weekdays in the remaining days starting from startDay.
    for (let i = 0; i < remainingDays; i++) {
        const day = (startDay + i) % 7;
        if (day >= 1 && day <= 5) {
            weekdays++;
        }
    }

