    const major = parseInt(parts[0] || '0', 10) || 0;
    const minor = parseInt(parts[1] || '0', 10) || 0;
    const patch = parseInt(parts[2] || '0', 10) || 0;
    let preIdentifiers = null;
    if (prerelease !== null) {
      preIdentifiers = prerelease.split('.').filter(id => id.length > 0);
    }
    return { major, minor, patch, prerelease: preIdentifiers };
  }

