  const aPre = a.prerelease;
  const bPre = b.prerelease;

  // No pre-release vs no pre-release
  if (aPre === null && bPre === null) return 0;
  // One has pre-release, other doesn't: pre-release is lower
  if (aPre === null) return 1; // a has no pre-release, b does -> a > b
  if (bPre === null) return -1; // a has pre-release, b doesn't -> a < b

