    const { text, width } = input;
    if (text == null) return [];
    const words = text.split(/\s+/).filter(w => w.length > 0);
    if (words.length === 0) return [];

    const lines = [];
    let current = "";

    for (const word of words) {
        if (word.length > width) {
            // Word longer than width goes on its own line
            if (current !== "") {
                lines.push(current);
                current = "";
            }
            lines.push(word);
        } else {
            if (current === "") {
                current = word;
            } else if (current.length + 1 + word.length <= width) {
                current = current + " " + word;
            } else {
                lines.push(current);
                current = word;
            }
        }
    }

    if (current !== "") {
        lines.push(current);
    }

    return lines;
}

