        if (newLength <= width) {
            currentLine.push(word);
            currentLength = newLength;
        } else {
            // Current line is full, push it and start a new one
            if (currentLine.length > 0) {
                lines.push(currentLine.join(" "));
            }
            currentLine = [word];
            currentLength = wordLen;
        }
    }

    // Don't forget the last line
    if (currentLine.length > 0) {
        lines.push(currentLine.join(" "));
    }

    return lines;
