function solve(input) {
    const n = BigInt(input);

    function gcd(a, b) {
        while (b !== 0n) {
            const t = a % b;
            a = b;
            b = t;
        }
        return a;
    }

    function isPrime(m) {
        if (m < 2n) return false;
        if (m === 2n || m === 3n) return true;
        if (m % 2n === 0n) return false;

        let d = m - 1n;
        let r = 0;
        while (d % 2n === 0n) {
            d /= 2n;
            r++;
        }

        const bases = [2n, 3n, 5n, 7n, 11n, 13n, 17n, 19n, 23n, 29n, 31n, 37n];
        for (const a of bases) {
            if (a % m === 0n) continue;
            let x = (a ** d) % m;
            if (x === 1n || x === m - 1n) continue;
            let composite = true;
            for (let i = 0; i < r - 1; i++) {
                x = (x * x) % m;
                if (x === m - 1n) {
                    composite = false;
                    break;
                }
            }
            if (composite) return false;
        }
        return true;
    }

    function pollardRho(n) {
        if (n % 2n === 0n) return 2n;
        if (n % 3n === 0n) return 3n;
        if (n % 5n === 0n) return 5n;

        for (let attempt = 0; attempt < 200; attempt++) {
            const c = (attempt + 1n) * 7n;
            const x0 = (attempt + 1n) * 13n + 1n;
            let x = x0;
            let y = x0;
            let d = 1n;
            let steps = 0;

            while (d === 1n && steps < 200000) {
                x = (x * x + c) % n;
                y = (y * y + c) % n;
                y = (y * y + c) % n;
                const diff = x > y ? x - y : y - x;
                d = gcd(diff, n);
                steps++;
            }

            if (d !== n && d !== 1n) return d;
        }
        return n;
    }

    function factor(n) {
        if (n < 2n) return [];
        if (isPrime(n)) return [n];

        const d = pollardRho(n);
        if (d === n || d === 1n) return [n];

        const a = factor(d);
        const b = factor(n / d);
        return a.concat(b);
    }

    const factors = factor(n);

    factors.sort((a, b) => a < b ? -1 : a > b ? 1 : 0);

    return factors.map(f => f.toString());
}

