    // - If thirdDigit > 5: round up
    // - If thirdDigit === 5:
    //   - If there are more non-zero digits after: round up
    //   - If there are no more digits (exactly half): round to even (2nd digit becomes even)

    let firstTwoFrac = fracPart.slice(0, 2).padEnd(2, '0');
