function addBigInts(a, b) {
    // Add two non-negative integers given as strings
    let i = a.length - 1;
    let j = b.length - 1;
    let carry = 0;
    let result = '';

    while (i >= 0 || j >= 0 || carry) {
        let sum = carry;
        if (i >= 0) sum += parseInt(a[i], 10);
        if (j >= 0) sum += parseInt(b[j], 10);
        carry = Math.floor(sum / 10);
        result = (sum % 10) + result;
        i--;
        j--;
    }

    return result.replace(/^0+/, '') || '0';
