    // Parse ISO date string "YYYY-MM-DD" into a UTC date object
    function parseISODate(s) {
        const [year, month, day] = s.split('-').map(Number);
        return new Date(Date.UTC(year, month - 1, day));
    }

    const startDate = parseISODate(from);
    const endDate = parseISODate(to);

    // Get the day of week for the start date (0=Sun, 1=Mon, ..., 6=Sat)
    const startDow = startDate.getUTCDay(); // 0 for Sunday

    // Total days in the half-open range [from, to)
    const totalDays = Math.round((endDate.getTime() - startDate.getTime()) / (1000 * 60 * 60 * 24));

    if (totalDays <= 0) return 0;

    // Count weekdays by iterating over full weeks and remaining days
    let count = 0;

    // Number of complete weeks
    const fullWeeks = Math.floor(totalDays / 7);
    count += fullWeeks * 5; // 5 weekdays per full week

    // Remaining days after full weeks
    const remainingDays = totalDays % 7;

    // Iterate over the remaining days starting from startDow
    for (let i = 0; i < remainingDays; i++) {
        const dow = (startDow + i) % 7;
        // Weekdays are Monday(1) through Friday(5)
        if (dow >= 1 && dow <= 5) {
            count++;
        }
    }

    return count;
}

