    for (const word of words) {
        if (word.length > width) {
            // Word is longer than width: go on its own line
            if (currentLine !== "") {
                lines.push(currentLine);
                currentLine = "";
            }
            lines.push(word);
        } else {
            if (currentLine === "") {
                currentLine = word;
            } else {
                // Check if adding word fits within width
                const candidate = currentLine + " " + word;
                if (candidate.length <= width) {
                    currentLine = candidate;
                } else {
                    lines.push(currentLine);
                    currentLine = word;
                }
            }
        }
    }

    if (currentLine !== "") {
        lines.push(currentLine);
    }

    return lines;
}

