    function isqrt(x) {
        if (x < 0n) throw new Error("negative");
        if (x === 0n) return 0n;
        let z = x;
        let y = (z + 1n) / 2n;
        while (y < z) {
            z = y;
            y = (z + x / z) / 2n;
        }
        return z;
    }

    // Start a from ceil(sqrt(N))
    let a = isqrt(N);
    if (a * a < N) a = a + 1n;

    // Fermat's factorization: find a, b such that N = a^2 - b^2
    // (a-b)(a+b) = N, so p = a-b, q = a+b
    while (true) {
        const a2 = a * a;
        const b2 = a2 - N;
        if (b2 >= 0n) {
            const b = isqrt(b2);
            if (b * b === b2) {
                const p = a - b;
                const q = a + b;
                if (p > 0n && q > 0n) {
                    if (p <= q) return [p.toString(10), q.toString(10)];
                    else return [q.toString(10), p.toString(10)];
                }
            }
        }
        a = a + 1n;
    }
}

